// Package rules reads a repository's vx.toml: what text merges cannot see.
//
//	[[unique]]      files matching glob may not share a key, e.g. two
//	                migrations with the same number; or, with content
//	                (and scope), lines inside them may not share a value,
//	                e.g. two fields numbered 12 in one proto message
//	[[generated]]   files matching glob are generated by command: vx never
//	                text-merges them and tells people to regenerate
//	[checks]        required = commands vx land should run (--run)
//	[[policy]]      how changes to some paths land: fast (default), gated
//	                (required checks run by vx and passing) or human (a
//	                person approves first)
//	[files]         large = the size above which vx status and vx land warn
//	                about a new file (default 1 MiB)
//	[[check]]       what must be proven before a change lands or ships:
//	                a command vx runs, or a check an agent, CI or a person
//	                reports (see checks.go)
//
// The package is pure: it reads trees and blobs through a blob.Store, so
// the server (land, ship, rebase) and the CLI (vx sync, vx land) apply the
// same rules to the same trees.
package rules

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/BurntSushi/toml"

	"github.com/TerracodeBA/vx/internal/blob"
	"github.com/TerracodeBA/vx/internal/engine"
	"github.com/TerracodeBA/vx/internal/hash"
	"github.com/TerracodeBA/vx/internal/object"
)

// File is where a repository keeps its rules: the root of the tree.
const File = "vx.toml"

// WarningRule marks a warning about a vx.toml rule.
const WarningRule engine.WarningKind = "rule"

// Unique says that files matching Glob may not share the first group of
// Key, matched against the file's base name (for example two migrations
// with the same number). With Content instead of Key, the rule looks inside
// the files: the first group of Content, matched against each line, may
// not be used twice, within each scope that Scope starts (see content.go).
type Unique struct {
	Name    string
	Glob    string
	Key     string
	Content string // optional, instead of Key: a regular expression matched against each line
	Scope   string // optional, with Content: a regular expression whose first group names a scope
}

// Generated says files matching Glob are generated by Command: vx never
// text-merges them and tells people to regenerate instead.
type Generated struct {
	Glob    string
	Command string
}

// Rules are a repository's vx.toml.
type Rules struct {
	Unique         []Unique
	Generated      []Generated
	RequiredChecks []string
	// Rebase is [automation] rebase: what vx does with an open effort when
	// its base branch moves. Empty means RebaseAuto.
	Rebase   string
	Policies []Policy
	// Checks are the [[check]] tables, in vx.toml order (Effective adds
	// the older [checks] required and [[policy]] tables as checks).
	Checks []CheckDef
	Source string // e.g. "vx.toml at 3f2a1c9d0e7b"; empty: none
	// LargeFile is [files] large in bytes: vx status and vx land warn
	// about new files above it. 0 means DefaultLargeFile.
	LargeFile int64
	// Ignored says what of vx.toml this vx does not know (keys or tables
	// of a newer vx) and so left out: a rule with an unknown key is
	// ignored as a whole. "vx.toml line 15: rule [[unique]] "proto-field"
	// uses key "scope", which this vx does not know; ...".
	Ignored []string
}

// [automation] rebase values.
const (
	RebaseAuto   = "auto"   // rebase when it replays cleanly, else say which files conflict
	RebaseNotify = "notify" // only say that the effort is behind, and whether it would conflict
	RebaseOff    = "off"    // do nothing
)

// RebaseMode is the [automation] rebase setting, RebaseAuto by default.
func (r Rules) RebaseMode() string {
	if r.Rebase == "" {
		return RebaseAuto
	}
	return r.Rebase
}

// DefaultLargeFile is the [files] large default: 1 MiB.
const DefaultLargeFile = 1 << 20

// LargeFileLimit is [files] large, DefaultLargeFile when unset.
func (r Rules) LargeFileLimit() int64 {
	if r.LargeFile <= 0 {
		return DefaultLargeFile
	}
	return r.LargeFile
}

// IsEmpty reports whether there are no rules.
func (r Rules) IsEmpty() bool {
	return len(r.Unique) == 0 && len(r.Generated) == 0 && len(r.RequiredChecks) == 0 && r.Rebase == "" && len(r.Policies) == 0 && len(r.Checks) == 0 && r.LargeFile == 0
}

// UniqueRule returns the [[unique]] rule called name.
func (r Rules) UniqueRule(name string) (Unique, bool) {
	for _, u := range r.Unique {
		if u.Name == name {
			return u, true
		}
	}
	return Unique{}, false
}

// Problem is one thing wrong in vx.toml.
type Problem struct {
	Line int // 1-based; 0 when the line is not known
	Msg  string
}

func (p Problem) String() string {
	if p.Line > 0 {
		return fmt.Sprintf("%s line %d: %s", File, p.Line, p.Msg)
	}
	return fmt.Sprintf("%s: %s", File, p.Msg)
}

// Error lists everything wrong in a vx.toml.
type Error struct {
	Problems []Problem
}

func (e *Error) Error() string {
	parts := make([]string, 0, len(e.Problems))
	for _, p := range e.Problems {
		parts = append(parts, p.String())
	}
	return strings.Join(parts, "\n")
}

type tomlUnique struct {
	Name    string `toml:"name"`
	Glob    string `toml:"glob"`
	Key     string `toml:"key"`
	Content string `toml:"content"`
	Scope   string `toml:"scope"`
}

type tomlGenerated struct {
	Glob    string `toml:"glob"`
	Command string `toml:"command"`
}

type tomlChecks struct {
	Required []string `toml:"required"`
}

type tomlPolicy struct {
	Paths     []string  `toml:"paths"`
	Mode      string    `toml:"mode"`
	Require   *[]string `toml:"require"`
	Approvers []string  `toml:"approvers"`
}

type tomlAutomation struct {
	Rebase string `toml:"rebase"`
}

type tomlFiles struct {
	Large any `toml:"large"` // "5 MiB", "500KB" or a number of bytes
}

type tomlFile struct {
	Unique     []tomlUnique    `toml:"unique"`
	Generated  []tomlGenerated `toml:"generated"`
	Checks     tomlChecks      `toml:"checks"`
	Automation tomlAutomation  `toml:"automation"`
	Policy     []tomlPolicy    `toml:"policy"`
	Files      tomlFiles       `toml:"files"`
	Check      []tomlCheck     `toml:"check"`
}

var known = map[string][]string{
	"":           {"[[unique]]", "[[generated]]", "[checks]", "[automation]", "[[policy]]", "[[check]]", "[files]"},
	"unique":     {"name", "glob", "key", "content", "scope"},
	"generated":  {"glob", "command"},
	"checks":     {"required"},
	"automation": {"rebase"},
	"policy":     {"paths", "mode", "require", "approvers"},
	"files":      {"large"},
	"check":      checkKeys,
}

var arrayTables = map[string]bool{"unique": true, "generated": true, "policy": true, "check": true}

var ruleName = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.-]*$`)

// Parse parses vx.toml. Syntax errors, unknown keys, invalid globs and
// regular expressions are errors (*Error) that say the line and what is
// wrong.
func Parse(data []byte) (Rules, error) {
	var f tomlFile
	md, err := toml.Decode(string(data), &f)
	if err != nil {
		var pe toml.ParseError
		if errors.As(err, &pe) {
			return Rules{}, &Error{Problems: []Problem{{Line: pe.Position.Line, Msg: pe.Message}}}
		}
		return Rules{}, &Error{Problems: []Problem{typeProblem(err)}}
	}
	loc := locate(data)
	var probs []Problem
	// Keys and tables this vx does not know may come from a newer vx: they
	// switch off only the rule they are in (or, outside rules, only
	// themselves), with a notice in Rules.Ignored, instead of making the
	// whole file unreadable for older servers and CLIs.
	var ignored []Problem
	skip := map[string]map[int]bool{} // array table -> indices of rules to ignore
	type pending struct {
		table, key string
		idx        int
	}
	var later []pending
	reported := map[string]bool{}
	for _, k := range md.Undecoded() {
		if len(k) > 1 && reported[k[:len(k)-1].String()] {
			reported[k.String()] = true
			continue
		}
		reported[k.String()] = true
		table, key := "", k[len(k)-1]
		if len(k) > 1 {
			table = k[:len(k)-1].String()
		}
		knownList := ""
		if ks, ok := known[table]; ok {
			knownList = " (known: " + strings.Join(ks, ", ") + ")"
		}
		switch {
		case table == "":
			ignored = append(ignored, Problem{Line: loc.find(table, key), Msg: fmt.Sprintf("table or key %q is unknown to this vx; ignored: update vx if it is new%s", key, knownList)})
		case arrayTables[table]:
			idxs := loc.indices(table, key)
			if len(idxs) == 0 { // not found (an inline table): name the key at least
				ignored = append(ignored, Problem{Line: loc.find(table, key), Msg: fmt.Sprintf("[[%s]] uses key %q, which this vx does not know; ignored: update vx%s", table, key, knownList)})
			}
			for _, i := range idxs {
				if skip[table] == nil {
					skip[table] = map[int]bool{}
				}
				skip[table][i] = true
				later = append(later, pending{table, key, i})
			}
		default:
			where := "[" + table + "]"
			ignored = append(ignored, Problem{Line: loc.find(table, key), Msg: fmt.Sprintf("%s uses key %q, which this vx does not know; ignored: update vx%s", where, key, knownList)})
		}
	}
	for _, p := range later {
		label := fmt.Sprintf("[[%s]] #%d", p.table, p.idx+1)
		switch {
		case p.table == "unique" && p.idx < len(f.Unique) && f.Unique[p.idx].Name != "":
			label = fmt.Sprintf("[[unique]] %q", f.Unique[p.idx].Name)
		case p.table == "policy" && p.idx < len(f.Policy) && len(f.Policy[p.idx].Paths) > 0:
			label = fmt.Sprintf("[[policy]] %q", f.Policy[p.idx].Paths[0])
		case p.table == "generated" && p.idx < len(f.Generated) && f.Generated[p.idx].Glob != "":
			label = fmt.Sprintf("[[generated]] %q", f.Generated[p.idx].Glob)
		case p.table == "check":
			if l, ok := checkLabel(f.Check, p.idx); ok {
				label = l
			}
		}
		ignored = append(ignored, Problem{Line: loc.at(p.table, p.idx, p.key),
			Msg: fmt.Sprintf("rule %s uses key %q, which this vx does not know; the rule is ignored: update vx (known: %s)", label, p.key, strings.Join(known[p.table], ", "))})
	}
	sort.SliceStable(ignored, func(i, j int) bool { return ignored[i].Line < ignored[j].Line })

	var r Rules
	names := map[string]bool{}
	for i, u := range f.Unique {
		if skip["unique"][i] {
			continue
		}
		line := func(key string) int { return loc.at("unique", i, key) }
		label := fmt.Sprintf("[[unique]] #%d", i+1)
		if u.Name != "" {
			label = fmt.Sprintf("[[unique]] %q", u.Name)
		}
		switch {
		case u.Name == "":
			probs = append(probs, Problem{line(""), label + ": name is missing (e.g. name = \"migration\"); vx reserve uses it"})
		case !ruleName.MatchString(u.Name):
			probs = append(probs, Problem{line("name"), fmt.Sprintf("%s: name may use letters, digits, '-', '_' and '.' only", label)})
		case names[u.Name]:
			probs = append(probs, Problem{line("name"), fmt.Sprintf("%s: a [[unique]] rule of that name is already defined", label)})
		}
		names[u.Name] = true
		if u.Glob == "" {
			probs = append(probs, Problem{line(""), label + ": glob is missing (e.g. glob = \"internal/store/migrations/*.sql\")"})
		} else if _, err := CompileGlob(u.Glob); err != nil {
			probs = append(probs, Problem{line("glob"), label + ": " + err.Error()})
		}
		group := func(key, re, part, example string) {
			if c, err := regexp.Compile(re); err != nil {
				probs = append(probs, Problem{line(key), fmt.Sprintf("%s: %s %q is not a valid regular expression: %v", label, key, re, err)})
			} else if c.NumSubexp() < 1 {
				probs = append(probs, Problem{line(key), fmt.Sprintf("%s: %s %q has no group: put the part that %s in parentheses, e.g. %s", label, key, re, part, example)})
			}
		}
		switch {
		case u.Key != "" && u.Content != "":
			probs = append(probs, Problem{line("content"), label + ": give key (unique file names) or content (unique values inside the files), not both"})
		case u.Content != "":
			group("content", u.Content, "must be unique", `'^\s*\w+\s+\w+\s*=\s*(\d+)'`)
		case u.Key == "":
			probs = append(probs, Problem{line(""), label + ": key is missing: a regular expression whose first group is the unique part of the file name, e.g. key = '^(\\d+)_' (or content = '...' for values inside the files)"})
		default:
			group("key", u.Key, "must be unique", `'^(\d+)_'`)
		}
		if u.Scope != "" {
			if u.Content == "" {
				probs = append(probs, Problem{line("scope"), label + ": scope only applies with content (values inside the files), not key"})
			} else {
				group("scope", u.Scope, "names the scope", `'^\s*message\s+(\w+)'`)
			}
		}
		r.Unique = append(r.Unique, Unique(u))
	}
	for i, g := range f.Generated {
		if skip["generated"][i] {
			continue
		}
		line := func(key string) int { return loc.at("generated", i, key) }
		label := fmt.Sprintf("[[generated]] #%d", i+1)
		if g.Glob == "" {
			probs = append(probs, Problem{line(""), label + ": glob is missing (e.g. glob = \"gen/**\")"})
		} else if _, err := CompileGlob(g.Glob); err != nil {
			probs = append(probs, Problem{line("glob"), label + ": " + err.Error()})
		}
		r.Generated = append(r.Generated, Generated{Glob: g.Glob, Command: strings.TrimSpace(g.Command)})
	}
	seen := map[string]bool{}
	for _, c := range f.Checks.Required {
		c = strings.TrimSpace(c)
		if c == "" {
			probs = append(probs, Problem{loc.at("checks", 0, "required"), "[checks] required has an empty command"})
			continue
		}
		if !seen[c] {
			seen[c] = true
			r.RequiredChecks = append(r.RequiredChecks, c)
		}
	}
	switch rb := strings.TrimSpace(f.Automation.Rebase); rb {
	case "", RebaseAuto, RebaseNotify, RebaseOff:
		r.Rebase = rb
	default:
		probs = append(probs, Problem{loc.at("automation", 0, "rebase"), fmt.Sprintf("[automation] rebase is %q; use \"auto\" (rebase when it replays cleanly), \"notify\" (only tell the effort) or \"off\"", rb)})
	}
	if f.Files.Large != nil {
		n, err := ParseSize(f.Files.Large)
		if err != nil {
			probs = append(probs, Problem{loc.at("files", 0, "large"), "[files] large: " + err.Error()})
		}
		r.LargeFile = n
	}
	var pprobs []Problem
	r.Policies, pprobs = parsePolicies(f.Policy, r.RequiredChecks, loc, skip["policy"])
	probs = append(probs, pprobs...)
	var cprobs []Problem
	r.Checks, cprobs = parseChecks(f.Check, loc, skip["check"])
	probs = append(probs, cprobs...)
	if len(probs) > 0 {
		sort.SliceStable(probs, func(i, j int) bool { return probs[i].Line < probs[j].Line })
		return Rules{}, &Error{Problems: probs}
	}
	for _, p := range ignored {
		r.Ignored = append(r.Ignored, p.String())
	}
	return r, nil
}

// parsePolicies checks the [[policy]] tables; required are the [checks]
// required commands, the default of require.
func parsePolicies(ps []tomlPolicy, required []string, loc locator, skip map[int]bool) ([]Policy, []Problem) {
	var out []Policy
	var probs []Problem
	for i, tp := range ps {
		if skip[i] {
			continue
		}
		line := func(key string) int { return loc.at("policy", i, key) }
		label := fmt.Sprintf("[[policy]] #%d", i+1)
		if len(tp.Paths) > 0 {
			label = fmt.Sprintf("[[policy]] %q", tp.Paths[0])
		}
		p := Policy{Mode: Mode(strings.TrimSpace(tp.Mode)), Line: line("")}
		if len(tp.Paths) == 0 {
			probs = append(probs, Problem{line("paths"), label + `: paths is missing: the files this policy covers, e.g. paths = ["internal/store/migrations/**"]`})
		}
		for _, g := range tp.Paths {
			g = strings.TrimSpace(g)
			if _, err := CompileGlob(g); err != nil {
				probs = append(probs, Problem{line("paths"), label + ": " + err.Error()})
				continue
			}
			p.Paths = append(p.Paths, g)
		}
		switch p.Mode {
		case "":
			probs = append(probs, Problem{line(""), label + `: mode is missing: "fast", "gated" or "human"`})
		case ModeFast, ModeGated, ModeHuman:
		default:
			probs = append(probs, Problem{line("mode"), fmt.Sprintf(`%s: mode %q is not one of "fast", "gated" or "human"`, label, tp.Mode)})
		}
		if tp.Require != nil {
			p.Require = []string{}
			seen := map[string]bool{}
			for _, c := range *tp.Require {
				c = strings.TrimSpace(c)
				if c == "" {
					probs = append(probs, Problem{line("require"), label + ": require has an empty command"})
					continue
				}
				if !seen[c] {
					seen[c] = true
					p.Require = append(p.Require, c)
				}
			}
			if p.Mode == ModeFast {
				probs = append(probs, Problem{line("require"), label + `: require has no effect with mode = "fast"; use mode = "gated" to require checks before landing`})
			}
		} else if p.Mode == ModeGated || p.Mode == ModeHuman {
			p.Require = append([]string(nil), required...)
		}
		if p.Mode == ModeGated && len(p.Require) == 0 && tp.Require == nil {
			probs = append(probs, Problem{line(""), label + `: mode = "gated" needs checks: set require = ["go test ./..."] in the policy, or required in [checks]`})
		} else if p.Mode == ModeGated && len(p.Require) == 0 {
			probs = append(probs, Problem{line("require"), label + `: mode = "gated" with require = [] checks nothing; list the checks, or use mode = "fast"`})
		}
		if len(tp.Approvers) > 0 && p.Mode != ModeHuman && p.Mode != "" {
			probs = append(probs, Problem{line("approvers"), fmt.Sprintf(`%s: approvers only apply to mode = "human", not %q`, label, p.Mode)})
		}
		seen := map[string]bool{}
		for _, a := range tp.Approvers {
			ap, err := ParseApprover(a)
			if err != nil {
				probs = append(probs, Problem{line("approvers"), label + ": " + err.Error()})
				continue
			}
			if s := ap.Kind + ":" + ap.Name; !seen[s] {
				seen[s] = true
				p.Approvers = append(p.Approvers, s)
			}
		}
		out = append(out, p)
	}
	return out, probs
}

var typeErr = regexp.MustCompile(`^toml: (?:line (\d+) )?\(last key "([^"]*)"\): incompatible types: TOML value has type (\S+); destination has type (\S+)$`)

// typeProblem turns a decoding error (a value of the wrong type) into a
// problem that says which key and what was expected.
func typeProblem(err error) Problem {
	m := typeErr.FindStringSubmatch(err.Error())
	if m == nil {
		return Problem{Msg: strings.TrimPrefix(err.Error(), "toml: ")}
	}
	line, _ := strconv.Atoi(m[1])
	what := func(t string) string {
		switch {
		case t == "string":
			return "a string"
		case strings.HasPrefix(t, "map"), t == "struct":
			return "a table"
		case strings.HasPrefix(t, "[]"), t == "slice":
			return "a list"
		case strings.HasPrefix(t, "int"), strings.HasPrefix(t, "float"):
			return "a number"
		case t == "bool":
			return "true or false"
		}
		return t
	}
	msg := fmt.Sprintf("%s must be %s, not %s", m[2], what(m[4]), what(m[3]))
	switch m[2] {
	case "unique", "generated", "policy":
		msg += fmt.Sprintf(": write each rule as a [[%s]] table", m[2])
	}
	return Problem{Line: line, Msg: msg}
}

// locator finds the line of a key in vx.toml, for error messages. It reads
// the file line by line: headers ([t], [[t]]) and "key = value" lines.
// Keys inside inline tables are not found; their errors point at the
// table's header instead.
type locator struct {
	keys    map[string]int // "table#index.key" -> line
	first   map[string]int // "table.key" -> first line
	headers map[string]int // "table#index" -> line
}

func locate(data []byte) locator {
	l := locator{keys: map[string]int{}, first: map[string]int{}, headers: map[string]int{}}
	table, idx := "", 0
	count := map[string]int{}
	sc := bufio.NewScanner(bytes.NewReader(data))
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	for n := 1; sc.Scan(); n++ {
		line := strings.TrimSpace(sc.Text())
		switch {
		case line == "" || strings.HasPrefix(line, "#"):
			continue
		case strings.HasPrefix(line, "[["):
			end := strings.Index(line, "]]")
			if end < 0 {
				continue
			}
			table = normKey(line[2:end])
			idx = count[table]
			count[table]++
		case strings.HasPrefix(line, "["):
			end := strings.Index(line, "]")
			if end < 0 {
				continue
			}
			table, idx = normKey(line[1:end]), 0
		default:
			eq := strings.Index(line, "=")
			if eq <= 0 {
				continue
			}
			key := normKey(line[:eq])
			id := table + "#" + strconv.Itoa(idx) + "." + key
			if _, ok := l.keys[id]; !ok {
				l.keys[id] = n
			}
			if _, ok := l.first[table+"."+key]; !ok {
				l.first[table+"."+key] = n
			}
			continue
		}
		if _, ok := l.headers[table+"#"+strconv.Itoa(idx)]; !ok {
			l.headers[table+"#"+strconv.Itoa(idx)] = n
		}
		if _, ok := l.first[table+"."]; !ok {
			l.first[table+"."] = n
		}
	}
	return l
}

func normKey(s string) string {
	parts := strings.Split(s, ".")
	for i, p := range parts {
		parts[i] = strings.Trim(strings.TrimSpace(p), `"'`)
	}
	return strings.Join(parts, ".")
}

// at is the line of key in the idx-th table called table, or of the
// table's header when the key is not there (or key is "").
func (l locator) at(table string, idx int, key string) int {
	if key != "" {
		if n, ok := l.keys[table+"#"+strconv.Itoa(idx)+"."+key]; ok {
			return n
		}
	}
	return l.headers[table+"#"+strconv.Itoa(idx)]
}

// indices are the positions of the tables called table that set key.
func (l locator) indices(table, key string) []int {
	var out []int
	for id := range l.keys {
		t, rest, ok := strings.Cut(id, "#")
		if !ok || t != table {
			continue
		}
		n, k, ok := strings.Cut(rest, ".")
		if !ok || k != key {
			continue
		}
		if i, err := strconv.Atoi(n); err == nil {
			out = append(out, i)
		}
	}
	sort.Ints(out)
	return out
}

// find is the first line of key in any table called table; a top-level
// name may also be a table header.
func (l locator) find(table, key string) int {
	if n, ok := l.first[table+"."+key]; ok {
		return n
	}
	full := key
	if table != "" {
		full = table + "." + key
	}
	if n, ok := l.first[full+"."]; ok {
		return n
	}
	return l.first[table+"."]
}

// At returns the rules in vx.toml at the root of tree. Without a vx.toml
// there are no rules and no error. Source says where they came from.
func At(ctx context.Context, s blob.Store, tree hash.Hash) (Rules, error) {
	if tree.IsZero() {
		return Rules{}, nil
	}
	e, ok, err := object.Lookup(ctx, s, tree, File)
	if err != nil || !ok {
		return Rules{}, err
	}
	if e.Mode == object.ModeDir || e.Mode == object.ModeSymlink {
		return Rules{}, &Error{Problems: []Problem{{Msg: "vx.toml must be a regular file at the repository root"}}}
	}
	data, err := blob.GetKind(ctx, s, hash.KindBlob, e.Hash)
	if err != nil {
		return Rules{}, err
	}
	r, err := Parse(data)
	if err != nil {
		return Rules{}, err
	}
	r.Source = File + " at tree " + tree.Short()
	return r, nil
}

// GeneratedMatcher compiles the [[generated]] globs once. The returned
// function reports whether path is generated and by which command (the
// first matching rule wins). Invalid globs match nothing.
func (r Rules) GeneratedMatcher() func(path string) (command string, ok bool) {
	type cg struct {
		g   Glob
		cmd string
	}
	var gs []cg
	for _, g := range r.Generated {
		if c, err := CompileGlob(g.Glob); err == nil {
			gs = append(gs, cg{c, g.Command})
		}
	}
	return func(path string) (string, bool) {
		for _, g := range gs {
			if g.g.Match(path) {
				return g.cmd, true
			}
		}
		return "", false
	}
}

// NotVerified describes a required check vx did not run:
//
//	required check `go vet ./...` (vx.toml) was not run by vx
func NotVerified(command string) string {
	return fmt.Sprintf("required check `%s` (%s) was not run by vx", command, File)
}

// MissingChecks returns the required checks of r that are not in ran
// (commands vx ran, compared after trimming spaces), in vx.toml order.
func MissingChecks(r Rules, ran []string) []string {
	have := map[string]bool{}
	for _, c := range ran {
		have[strings.TrimSpace(c)] = true
	}
	var out []string
	for _, c := range r.RequiredChecks {
		if !have[c] {
			out = append(out, c)
		}
	}
	return out
}

// MergeOptions are the engine options of a merge whose sides are trees:
// the [[generated]] rules of every one of them, so a generated file is
// never text-merged whichever side declared it. A vx.toml that does not
// parse adds nothing (the land reports it).
func MergeOptions(ctx context.Context, s blob.Store, trees ...hash.Hash) []engine.MergeOption {
	var matchers []func(string) (string, bool)
	seen := map[hash.Hash]bool{}
	for _, t := range trees {
		if seen[t] {
			continue
		}
		seen[t] = true
		r, err := At(ctx, s, t)
		if err != nil || len(r.Generated) == 0 {
			continue
		}
		matchers = append(matchers, r.GeneratedMatcher())
	}
	if len(matchers) == 0 {
		return nil
	}
	return []engine.MergeOption{engine.WithGenerated(func(path string) (string, bool) {
		for _, m := range matchers {
			if cmd, ok := m(path); ok {
				return cmd, true
			}
		}
		return "", false
	})}
}

// Check reports [[unique]] violations in tree as warnings of kind
// WarningRule, limited to keys used by a file that is new or changed
// between base and tree, so a clash that predates the change is not
// repeated on every land. base may be zero: every file counts as new.
// Content rules (see content.go) report values used more often in tree
// than in base, with Decl = "SCOPE VALUE" (or "VALUE" outside scopes).
//
// Each warning has Name = the rule name, Decl = the shared key, Files =
// the full paths of every file using it (sorted), Path = the first of them
// that changed, and a Detail for people:
//
//	migration 008 is used by 008_effort_rebases.sql and 008_orgs.sql (rule migration in vx.toml)
func Check(ctx context.Context, s blob.Store, r Rules, base, tree hash.Hash) ([]engine.Warning, error) {
	if len(r.Unique) == 0 || tree.IsZero() || base == tree {
		return nil, nil
	}
	changed := map[string]bool{}
	if !base.IsZero() {
		cs, err := object.DiffTrees(ctx, s, base, tree)
		if err != nil {
			return nil, err
		}
		for _, c := range cs {
			if c.Op != object.OpDelete {
				changed[c.Path] = true
			}
		}
	}
	var out []engine.Warning
	for _, u := range r.Unique {
		g, err := CompileGlob(u.Glob)
		if err != nil {
			continue
		}
		if !base.IsZero() && !anyMatch(changed, g) {
			continue // nothing this rule covers changed
		}
		if u.IsContent() {
			ws, err := checkContent(ctx, s, u, g, base, tree)
			if err != nil {
				return nil, err
			}
			out = append(out, ws...)
			continue
		}
		key, err := regexp.Compile(u.Key)
		if err != nil || key.NumSubexp() < 1 {
			continue
		}
		files, err := Files(ctx, s, tree, g)
		if err != nil {
			return nil, err
		}
		byKey := map[string][]string{}
		var order []string
		for _, p := range files {
			k, ok := KeyOf(key, p)
			if !ok {
				continue
			}
			if _, seen := byKey[k]; !seen {
				order = append(order, k)
			}
			byKey[k] = append(byKey[k], p)
		}
		sort.Strings(order)
		for _, k := range order {
			ps := byKey[k]
			if len(ps) < 2 {
				continue
			}
			sort.Strings(ps)
			first := ""
			for _, p := range ps {
				if base.IsZero() || changed[p] {
					first = p
					break
				}
			}
			if first == "" {
				continue
			}
			out = append(out, engine.Warning{
				Path: first, Kind: WarningRule, Name: u.Name, Decl: k, Files: ps,
				Detail: fmt.Sprintf("%s %s is used by %s (rule %s in %s)", u.Name, k, joinAnd(displayPaths(ps)), u.Name, File),
			})
		}
	}
	return out, nil
}

func anyMatch(paths map[string]bool, g Glob) bool {
	for p := range paths {
		if g.Match(p) {
			return true
		}
	}
	return false
}

// KeyOf returns the first group of key matched against the base name of
// path.
func KeyOf(key *regexp.Regexp, path string) (string, bool) {
	name := path[strings.LastIndexByte(path, '/')+1:]
	m := key.FindStringSubmatch(name)
	if m == nil || m[1] == "" {
		return "", false
	}
	return m[1], true
}

// Files lists the files of tree that match g, sorted. Only the glob's
// literal directory is read.
func Files(ctx context.Context, s blob.Store, tree hash.Hash, g Glob) ([]string, error) {
	root := tree
	if d := g.Dir(); d != "" {
		e, ok, err := object.Lookup(ctx, s, tree, d)
		if err != nil {
			return nil, err
		}
		if !ok || e.Mode != object.ModeDir {
			return nil, nil
		}
		root = e.Hash
	}
	m, err := object.ReadManifest(ctx, s, root)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, p := range m.Paths() {
		if g.Dir() != "" {
			p = g.Dir() + "/" + p
		}
		if g.Match(p) {
			out = append(out, p)
		}
	}
	return out, nil
}

// displayPaths shortens paths to base names when they share a directory.
func displayPaths(ps []string) []string {
	dir := func(p string) string { return p[:strings.LastIndexByte(p, '/')+1] }
	for _, p := range ps[1:] {
		if dir(p) != dir(ps[0]) {
			return ps
		}
	}
	out := make([]string, len(ps))
	for i, p := range ps {
		out[i] = p[len(dir(p)):]
	}
	return out
}

func joinAnd(xs []string) string {
	switch len(xs) {
	case 0:
		return ""
	case 1:
		return xs[0]
	}
	return strings.Join(xs[:len(xs)-1], ", ") + " and " + xs[len(xs)-1]
}

// ParseSize reads a size such as "1 MiB", "500KB", "2MB" or a number of
// bytes (1048576). KB, MB and GB are powers of 1000; KiB, MiB and GiB of
// 1024.
func ParseSize(v any) (int64, error) {
	switch v := v.(type) {
	case int64:
		if v <= 0 {
			return 0, fmt.Errorf("%d is not a positive size", v)
		}
		return v, nil
	case string:
		s := strings.TrimSpace(v)
		i := 0
		for i < len(s) && (s[i] >= '0' && s[i] <= '9' || s[i] == '.') {
			i++
		}
		num, err := strconv.ParseFloat(s[:i], 64)
		if i == 0 || err != nil || num <= 0 {
			return 0, fmt.Errorf("%q is not a size; write it like \"1 MiB\", \"500KB\" or 1048576", v)
		}
		mult := map[string]float64{"": 1, "B": 1, "KB": 1e3, "MB": 1e6, "GB": 1e9, "KIB": 1 << 10, "MIB": 1 << 20, "GIB": 1 << 30, "K": 1 << 10, "M": 1 << 20, "G": 1 << 30}
		unit := strings.ToUpper(strings.TrimSpace(s[i:]))
		m, ok := mult[unit]
		if !ok {
			return 0, fmt.Errorf("%q has an unknown unit %q; use B, KB, MB, GB, KiB, MiB or GiB", v, strings.TrimSpace(s[i:]))
		}
		return int64(num * m), nil
	}
	return 0, fmt.Errorf("%v is not a size; write it like \"1 MiB\" or a number of bytes", v)
}
